<?php
// A-FIRST course setup: builds review (microlearning) units from a module's own course text (D-24).
//
// Pure functions with no Moodle dependency, so selfcheck.php can test them with plain PHP.
// build_microlearning.php supplies the SCORM text and the installed H5P library versions.
//
// Extraction only: every line in a unit is copied verbatim from the course text, so the content
// owner can trace it (REVIEW.md lists each line with its line number). Nothing is paraphrased or
// generated by a model. A unit has:
//  - the module's learning objectives (intro text);
//  - key points: an Accordion with one panel per course heading (title) and the first sentences
//    under it;
//  - key terms: Dialog Cards from definition sentences ("X is ...", "X refers to ...").

/** Words that start a sentence but are not a term being defined. */
const AFIRST_ML_NOT_TERMS = ['this', 'these', 'that', 'those', 'it', 'its', 'there', 'every', 'each', 'when',
    'you', 'we', 'our', 'your', 'which', 'what', 'why', 'how', 'good', 'most', 'many', 'some', 'such', 'all',
    'both', 'here', 'if', 'once', 'in', 'for', 'as', 'one', 'another', 'instead', 'without',
    'because', 'they', 'he', 'she', 'not', 'no', 'also', 'so', 'then', 'now', 'only', 'other', 'their',
    'the', 'to', 'but', 'and', 'or', 'identify', 'ensure', 'check', 'imagine', 'focusing', 'knowing', 'make', 'use',
    'select', 'think', 'remember', 'consider'];

/** Words that, right after "is/are", mark a comment ("X is important, but ...") rather than a definition. */
const AFIRST_ML_NOT_DEFINITIONS = ['important', 'essential', 'valid', 'invalid', 'higher', 'lower', 'not', 'once',
    'also', 'crucial', 'loaded', 'in', 'still', 'now', 'then', 'there', 'here', 'likely', 'unlikely', 'correct',
    'incorrect', 'right', 'wrong', 'true', 'false', 'that'];

/** Headings that introduce navigation, scenarios or quizzes rather than content. */
const AFIRST_ML_SKIP_HEADINGS = '/^(m\d+\.\d+\b|introduction|learning objectives?|hello|welcome|step\b|scene\b|scenario|'
    . 'knowledge check|quiz|let\'?s|let’s|select|expand|click|help her|help him|help them|start|continue|'
    . 'well done|congratulations|references?|further reading|note\b|tip\b|key (point|message)|left$|right$|'
    . 'icon|important$|remember|example$)/i';

/**
 * Splits a paragraph into sentences.
 *
 * @return string[]
 */
function afirst_ml_sentences(string $paragraph): array {
    $parts = preg_split('/(?<=[.!?])\s+(?=[A-Z“"‘(])/u', trim($paragraph)) ?: [];
    return array_values(array_filter(array_map('trim', $parts), 'strlen'));
}

/**
 * Number of words in a string.
 */
function afirst_ml_words(string $s): int {
    return count(preg_split('/\s+/u', trim($s), -1, PREG_SPLIT_NO_EMPTY));
}

/**
 * Extracts a review unit from plain course text (one block per line, blank lines between blocks).
 *
 * @param string $text Course text as produced by scorm_text_extractor.
 * @param int $maxpanels Most key-point panels.
 * @param int $maxcards Most key-term cards.
 * @return array{objectives: array<int, array{text: string, line: int}>,
 *               panels: array<int, array{title: string, text: string, line: int}>,
 *               cards: array<int, array{front: string, back: string, line: int}>}
 *         Line numbers are 1-based positions in $text.
 */
function afirst_ml_extract(string $text, int $maxpanels = 10, int $maxcards = 10): array {
    $lines = preg_split('/\R/u', $text);
    $n = count($lines);
    $trimmed = array_map('trim', $lines);
    $unit = ['objectives' => [], 'panels' => [], 'cards' => []];

    // Learning objectives: the list after "... you will be able to:".
    for ($i = 0; $i < $n; $i++) {
        if (!preg_match('/you will be able to:?$/i', $trimmed[$i])) {
            continue;
        }
        $j = $i + 1;
        while ($j < $n && $trimmed[$j] === '') {
            $j++;
        }
        for (; $j < $n && $trimmed[$j] !== '' && mb_strlen($trimmed[$j]) <= 200; $j++) {
            $unit['objectives'][] = ['text' => rtrim($trimmed[$j], '.;'), 'line' => $j + 1];
        }
        break;
    }

    // Key points: a heading line followed directly by a paragraph.
    $seentitles = [];
    for ($i = 1; $i < $n - 1 && count($unit['panels']) < $maxpanels; $i++) {
        $title = $trimmed[$i];
        $words = afirst_ml_words($title);
        if ($title === '' || $words < 1 || $words > 9 || preg_match('/[.?!:;,]$/u', $title)
                || $trimmed[$i - 1] !== '' || preg_match(AFIRST_ML_SKIP_HEADINGS, $title)
                || isset($seentitles[mb_strtolower($title)])) {
            continue;
        }
        $next = $i + 1;
        if ($trimmed[$next] === '' && $next + 1 < $n) {
            $next++; // A heading may be followed by one blank line.
        }
        $para = $trimmed[$next];
        if (!str_ends_with($para, '.') || afirst_ml_words($para) < 12 || str_contains($para, '?')
                || !preg_match('/^[\p{Lu}“"]/u', $para)) {
            continue;
        }
        $sentences = afirst_ml_sentences($para);
        $body = $sentences[0];
        if (isset($sentences[1]) && mb_strlen($body . ' ' . $sentences[1]) <= 400) {
            $body .= ' ' . $sentences[1];
        }
        $seentitles[mb_strtolower($title)] = true;
        $unit['panels'][] = ['title' => $title, 'text' => $body, 'line' => $next + 1];
    }

    // Key terms: definition sentences opening a paragraph.
    $seenterms = [];
    $prev = '';
    for ($i = 0; $i < $n && count($unit['cards']) < $maxcards; $i++) {
        $line = $trimmed[$i];
        if ($line === '') {
            continue;
        }
        $previous = $prev;
        $prev = $line;
        if (str_ends_with($previous, '?') || str_contains($line, '?') || !str_ends_with($line, '.')) {
            continue; // Quiz questions and their options.
        }
        $sentence = afirst_ml_sentences($line)[0] ?? '';
        if (afirst_ml_words($sentence) < 8 || !preg_match(
                '/^(?:(?:A|An)\s+)?([A-Za-z][\p{L}\-’\']*(?:\s+[\p{L}\-’\'()]+){0,4}?)\s+(is|are|refers to|means)\s+(.{20,})$/u',
                $sentence, $m)) {
            continue;
        }
        if (!preg_match('/^(A|An)\s/', $sentence) && !preg_match('/^\p{Lu}/u', $m[1])) {
            continue; // Lower-case start: a list item, not a definition.
        }
        $term = mb_strtoupper(mb_substr($m[1], 0, 1)) . mb_substr($m[1], 1); // "A dashboard is" -> "Dashboard".
        $first = mb_strtolower(preg_split('/\s+/u', $term)[0]);
        $predicate = mb_strtolower(preg_split('/[\s,]+/u', $m[3])[0]);
        if (in_array($first, AFIRST_ML_NOT_TERMS, true) || in_array($predicate, AFIRST_ML_NOT_DEFINITIONS, true)
                || isset($seenterms[mb_strtolower($term)])) {
            continue;
        }
        $seenterms[mb_strtolower($term)] = true;
        $unit['cards'][] = ['front' => $term, 'back' => $sentence, 'line' => $i + 1];
    }
    return $unit;
}

/**
 * Deterministic UUID for an H5P sub-content, so rebuilding a unit gives the same package.
 */
function afirst_ml_uuid(string $seed): string {
    $h = md5($seed);
    return sprintf('%s-%s-4%s-%x%s-%s', substr($h, 0, 8), substr($h, 8, 4), substr($h, 13, 3),
        8 | (hexdec($h[16]) & 3), substr($h, 17, 3), substr($h, 20, 12));
}

/**
 * HTML paragraph for H5P text fields.
 */
function afirst_ml_p(string $s): string {
    return '<p>' . htmlspecialchars($s, ENT_QUOTES | ENT_HTML5, 'UTF-8') . '</p>';
}

/**
 * Library reference "H5P.Name major.minor".
 *
 * @param array<string, array{0: int, 1: int}> $versions
 */
function afirst_ml_lib(string $name, array $versions): string {
    if (!isset($versions[$name])) {
        throw new InvalidArgumentException("H5P library $name is not installed");
    }
    return $name . ' ' . $versions[$name][0] . '.' . $versions[$name][1];
}

/**
 * h5p.json for a unit.
 *
 * @param array<string, array{0: int, 1: int}> $versions Installed versions of H5P.Column, H5P.AdvancedText,
 *     H5P.Accordion and H5P.Dialogcards.
 */
function afirst_ml_h5p_json(string $title, array $versions): array {
    $deps = [];
    foreach (['H5P.Column', 'H5P.AdvancedText', 'H5P.Accordion', 'H5P.Dialogcards'] as $name) {
        afirst_ml_lib($name, $versions);
        $deps[] = ['machineName' => $name, 'majorVersion' => $versions[$name][0], 'minorVersion' => $versions[$name][1]];
    }
    return ['title' => $title, 'language' => 'en', 'mainLibrary' => 'H5P.Column', 'embedTypes' => ['div'],
        'license' => 'U', 'defaultLanguage' => 'en', 'preloadedDependencies' => $deps];
}

/**
 * content/content.json for a unit (H5P.Column: intro text, key-point accordion, key-term cards).
 *
 * @param string $code Module code, e.g. "1.1" (seeds the sub-content ids).
 * @param array $unit Output of afirst_ml_extract().
 * @param array<string, array{0: int, 1: int}> $versions
 */
function afirst_ml_content(string $code, string $title, array $unit, array $versions): array {
    $text = afirst_ml_lib('H5P.AdvancedText', $versions);
    $meta = fn(string $type, string $t) => ['contentType' => $type, 'license' => 'U', 'title' => $t];
    $items = [];

    $intro = '<h2>' . htmlspecialchars($title, ENT_QUOTES | ENT_HTML5, 'UTF-8') . '</h2>'
        . afirst_ml_p('A short review of this module, taken word for word from the module itself.');
    if ($unit['objectives']) {
        $intro .= afirst_ml_p('By the end of this module, you will be able to:') . '<ul>';
        foreach ($unit['objectives'] as $o) {
            $intro .= '<li>' . htmlspecialchars($o['text'], ENT_QUOTES | ENT_HTML5, 'UTF-8') . '</li>';
        }
        $intro .= '</ul>';
    }
    $items[] = ['content' => ['library' => $text, 'params' => ['text' => $intro],
        'subContentId' => afirst_ml_uuid("$code/intro"), 'metadata' => $meta('Text', 'Introduction')],
        'useSeparator' => 'auto'];

    if ($unit['panels']) {
        $panels = [];
        foreach ($unit['panels'] as $k => $p) {
            $panels[] = ['title' => $p['title'], 'content' => ['library' => $text,
                'params' => ['text' => afirst_ml_p($p['text'])],
                'subContentId' => afirst_ml_uuid("$code/panel/$k"), 'metadata' => $meta('Text', $p['title'])]];
        }
        $items[] = ['content' => ['library' => $text, 'params' => ['text' => '<h3>Key points</h3>'],
            'subContentId' => afirst_ml_uuid("$code/kp-heading"), 'metadata' => $meta('Text', 'Key points')],
            'useSeparator' => 'disabled'];
        $items[] = ['content' => ['library' => afirst_ml_lib('H5P.Accordion', $versions),
            'params' => ['panels' => $panels, 'hTag' => 'h4'],
            'subContentId' => afirst_ml_uuid("$code/accordion"), 'metadata' => $meta('Accordion', 'Key points')],
            'useSeparator' => 'auto'];
    }

    if ($unit['cards']) {
        $dialogs = [];
        foreach ($unit['cards'] as $c) {
            $dialogs[] = ['text' => afirst_ml_p($c['front']), 'answer' => afirst_ml_p($c['back']), 'tips' => (object)[]];
        }
        $items[] = ['content' => ['library' => afirst_ml_lib('H5P.Dialogcards', $versions),
            'params' => ['title' => '<p>Key terms</p>',
                'description' => afirst_ml_p('Read the term, try to recall its meaning, then turn the card.'),
                'mode' => 'normal', 'dialogs' => $dialogs,
                'behaviour' => ['enableRetry' => true, 'disableBackwardsNavigation' => false,
                    'scaleTextNotCard' => false, 'randomCards' => false]],
            'subContentId' => afirst_ml_uuid("$code/cards"), 'metadata' => $meta('Dialog Cards', 'Key terms')],
            'useSeparator' => 'auto'];
    }
    return ['content' => $items];
}

/**
 * Markdown section of the content owner's review sheet for one unit.
 */
function afirst_ml_review_md(string $code, string $title, string $sourcename, array $unit): string {
    $esc = fn(string $s) => str_replace('|', '\|', $s);
    $md = "## Review: Module $code — $title\n\nSource: SCORM \"$sourcename\". Line numbers refer to the text "
        . "the assistant imported from it. Every line below is copied word for word.\n\n";
    $md .= "**Learning objectives** (" . count($unit['objectives']) . ")\n\n";
    foreach ($unit['objectives'] as $o) {
        $md .= "- {$o['text']} _(line {$o['line']})_\n";
    }
    $md .= "\n**Key points** (" . count($unit['panels']) . ")\n\n| Heading | Text | Line |\n|---|---|---|\n";
    foreach ($unit['panels'] as $p) {
        $md .= "| {$esc($p['title'])} | {$esc($p['text'])} | {$p['line']} |\n";
    }
    $md .= "\n**Key terms** (" . count($unit['cards']) . ")\n\n| Term | Card back | Line |\n|---|---|---|\n";
    foreach ($unit['cards'] as $c) {
        $md .= "| {$esc($c['front'])} | {$esc($c['back'])} | {$c['line']} |\n";
    }
    $md .= "\nOwner decision: ☐ approve as is ☐ approve with the changes noted ☐ reject\n\n";
    return $md;
}
